<?php

    namespace Database\Seeders\Master;

    use App\Models\Master\Province;
    use App\Models\Master\City;
	use App\Models\Master\District;
    use App\Models\Master\SubDistrict;
    use Illuminate\Database\Console\Seeds\WithoutModelEvents;
    use Illuminate\Database\Seeder;

    class SubDistrictsSeeder extends Seeder
    {
        /**
         * Run the database seeds.
         *
         * @return void
         */
        public function run()
        {
            $data = $this->data();

            foreach ($data as $value) {
                SubDistrict::create([
                    'country_id'  => 1,
                    'province_id' => $this->getProvinceId($value['province_id']),
                    'city_id'     => $this->getCityId($value['city_id']),
                    'district_id' => $this->getDistrictId($value['district_id']),
                    'area_code'   => $value['area_code'],
                    'name'        => $value['name']
                ]);
            }
        }

        function getProvinceId($areacode)
        {
            $province = Province::where('area_code', $areacode)->first();

            return $province->id;
        }

        function getCityId($areacode)
        {
            $city = City::where('area_code', $areacode)->first();

            return $city->id;
        }

        function getDistrictId($areacode)
        {
            $district = District::where('area_code', $areacode)->first();

            return $district->id;
        }


